package main

import (
	"fmt"
	"os"
	"path/filepath"
)

// findRoot go.mod joylashgan papkani yuqoriga qarab qidiradi.
func findRoot(dir string) (string, bool) {
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir { // ildizga yetdik
			return "", false
		}
		dir = parent
	}
}

func main() {
	tmp, _ := os.MkdirTemp("", "modul")
	defer os.RemoveAll(tmp)

	deep := filepath.Join(tmp, "internal", "store")
	os.MkdirAll(deep, 0o755)
	os.WriteFile(filepath.Join(tmp, "go.mod"), []byte("module example.com/hello\n"), 0o644)

	root, ok := findRoot(deep)
	rel, _ := filepath.Rel(tmp, root)
	fmt.Println("topildi:", ok)
	fmt.Println("ildizga nisbatan yo'l:", rel)
	data, _ := os.ReadFile(filepath.Join(root, "go.mod"))
	fmt.Printf("go.mod: %q\n", data)
}

