package main

import (
	"fmt"
	"strings"
)

const gomod = `module example.com/hello

go 1.27.2

require rsc.io/quote v1.5.2

require (
	golang.org/x/text v0.0.0-20170915032832-14c0d48ead0c // indirect
	rsc.io/sampler v1.3.0 // indirect
)
`

type Req struct {
	Path, Version string
	Indirect      bool
}

func parseReq(s string) Req {
	code, comment, _ := strings.Cut(s, "//")
	f := strings.Fields(code)
	return Req{f[0], f[1], strings.TrimSpace(comment) == "indirect"}
}

func main() {
	var module, goVersion string
	var reqs []Req
	inBlock := false
	for _, line := range strings.Split(gomod, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case line == "":
		case strings.HasPrefix(line, "module "):
			module = strings.TrimPrefix(line, "module ")
		case strings.HasPrefix(line, "go "):
			goVersion = strings.TrimPrefix(line, "go ")
		case line == "require (":
			inBlock = true
		case line == ")":
			inBlock = false
		case strings.HasPrefix(line, "require "):
			reqs = append(reqs, parseReq(strings.TrimPrefix(line, "require ")))
		case inBlock:
			reqs = append(reqs, parseReq(line))
		}
	}

	fmt.Println("Modul:", module)
	fmt.Println("Go:", goVersion)
	for _, r := range reqs {
		kind := "to'g'ridan-to'g'ri"
		if r.Indirect {
			kind = "bilvosita"
		}
		fmt.Printf("  %s %s (%s)\n", r.Path, r.Version, kind)
	}
}

package main

import (
	"fmt"
	"slices"
	"strings"
)

type Req struct {
	Path, Version string
	Indirect      bool
}

func block(b *strings.Builder, reqs []Req) {
	switch len(reqs) {
	case 0:
		return
	case 1:
		fmt.Fprintf(b, "\nrequire %s %s", reqs[0].Path, reqs[0].Version)
		if reqs[0].Indirect {
			b.WriteString(" // indirect")
		}
		b.WriteString("\n")
	default:
		b.WriteString("\nrequire (\n")
		for _, r := range reqs {
			fmt.Fprintf(b, "\t%s %s", r.Path, r.Version)
			if r.Indirect {
				b.WriteString(" // indirect")
			}
			b.WriteString("\n")
		}
		b.WriteString(")\n")
	}
}

func main() {
	reqs := []Req{
		{"rsc.io/sampler", "v1.3.0", true},
		{"rsc.io/quote", "v1.5.2", false},
		{"golang.org/x/text", "v0.0.0-20170915032832-14c0d48ead0c", true},
	}
	slices.SortFunc(reqs, func(a, b Req) int { return strings.Compare(a.Path, b.Path) })

	var direct, indirect []Req
	for _, r := range reqs {
		if r.Indirect {
			indirect = append(indirect, r)
		} else {
			direct = append(direct, r)
		}
	}

	var b strings.Builder
	b.WriteString("module example.com/hello\n\ngo 1.27.2\n")
	block(&b, direct)
	block(&b, indirect)
	fmt.Print(b.String())
}

