import (
	"fmt"
	"strings"
)

var imports = map[string][]string{
	"example.com/hello":          {"fmt", "rsc.io/quote"},
	"rsc.io/quote":               {"rsc.io/sampler"},
	"rsc.io/sampler":             {"golang.org/x/text/language"},
	"golang.org/x/text/language": {"golang.org/x/text/internal/tag"},
}

func why(target string) []string {
	parent := map[string]string{"example.com/hello": ""}
	queue := []string{"example.com/hello"}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == target {
			var path []string
			for n := cur; n != ""; n = parent[n] {
				path = append([]string{n}, path...)
			}
			return path
		}
		for _, next := range imports[cur] {
			if _, seen := parent[next]; !seen {
				parent[next] = cur
				queue = append(queue, next)
			}
		}
	}
	return nil
}

func main() {
	for _, t := range []string{"golang.org/x/text/language", "github.com/google/uuid"} {
		if path := why(t); path != nil {
			fmt.Println(t, "kerak:")
			fmt.Println("  " + strings.Join(path, "\n  "))
		} else {
			fmt.Println(t, "kerak emas")
		}
	}
}

package main

import (
	"cmp"
	"fmt"
	"slices"
	"sort"
	"strconv"
	"strings"
)

type Version struct{ Major, Minor, Patch int }

func parse(s string) Version {
	parts := strings.Split(strings.TrimPrefix(s, "v"), ".")
	n := func(i int) int { v, _ := strconv.Atoi(parts[i]); return v }
	return Version{n(0), n(1), n(2)}
}

func compare(a, b string) int {
	x, y := parse(a), parse(b)
	return cmp.Or(
		cmp.Compare(x.Major, y.Major),
		cmp.Compare(x.Minor, y.Minor),
		cmp.Compare(x.Patch, y.Patch),
	)
}

func main() {
	versions := []string{"v1.10.0", "v1.2.0", "v1.9.1", "v1.2.10", "v1.2.9"}

	byText := slices.Clone(versions)
	sort.Strings(byText)
	fmt.Println("matn bo'yicha:  ", byText)

	bySemver := slices.Clone(versions)
	slices.SortFunc(bySemver, compare)
	fmt.Println("semver bo'yicha:", bySemver)
}

package main

import (
	"fmt"
	"maps"
	"slices"
	"strings"
)

// graph: "modul@versiya" -> u talab qiladigan modullar
var graph = map[string][]string{
	"app":      {"A@v1.2.0", "B@v1.1.0"},
	"A@v1.2.0": {"C@v1.3.0"},
	"B@v1.1.0": {"C@v1.5.0"},
	"C@v1.5.0": {"D@v1.0.0"},
}

func parse(v string) []int {
	var p [3]int
	fmt.Sscanf(v, "v%d.%d.%d", &p[0], &p[1], &p[2])
	return p[:]
}

func main() {
	selected := map[string]string{} // modul -> tanlangan versiya
	seen := map[string]bool{}

	var visit func(node string)
	visit = func(node string) {
		if seen[node] {
			return
		}
		seen[node] = true
		if name, ver, ok := strings.Cut(node, "@"); ok {
			cur, has := selected[name]
			if !has || slices.Compare(parse(ver), parse(cur)) > 0 {
				selected[name] = ver
			}
		}
		for _, dep := range graph[node] {
			visit(dep)
		}
	}
	visit("app")

	for _, name := range slices.Sorted(maps.Keys(selected)) {
		fmt.Println(name, selected[name])
	}
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

func patchOf(v string) int {
	n, _ := strconv.Atoi(v[strings.LastIndex(v, ".")+1:])
	return n
}

func main() {
	current := map[string]string{
		"example.com/a": "v1.4.1",
		"example.com/b": "v2.0.3",
	}
	available := map[string][]string{
		"example.com/a": {"v1.4.1", "v1.4.2", "v1.4.5", "v1.5.0", "v2.0.0"},
		"example.com/b": {"v2.0.3", "v2.1.0"},
	}

	for _, mod := range []string{"example.com/a", "example.com/b"} {
		cur := current[mod]
		minor := cur[:strings.LastIndex(cur, ".")] // v1.4
		best := cur
		for _, v := range available[mod] {
			if strings.HasPrefix(v, minor+".") && patchOf(v) > patchOf(best) {
				best = v
			}
		}
		fmt.Printf("%s: %s -> %s\n", mod, cur, best)
	}
}

