package main

import (
	"fmt"
	"regexp"
)

var (
	full   = regexp.MustCompile(`^v\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$`)
	prefix = regexp.MustCompile(`^v\d+(\.\d+)?$`)
	hash   = regexp.MustCompile(`^[0-9a-f]{7,40}$`)
)

func kind(q string) string {
	switch {
	case q == "latest" || q == "upgrade" || q == "patch":
		return "kalit so'z"
	case q == "none":
		return "olib tashlash"
	case full.MatchString(q):
		return "aniq versiya"
	case prefix.MatchString(q):
		return "versiya prefiksi (eng katta mos versiya)"
	case hash.MatchString(q):
		return "commit (pseudo-versiya hosil bo'ladi)"
	default:
		return "branch yoki teg nomi"
	}
}

func main() {
	for _, q := range []string{"latest", "none", "v1.5.2", "v1.5.3-pre1", "v1.5", "v2", "5d9f230bcfba", "master"} {
		fmt.Printf("@%-13s %s\n", q, kind(q))
	}
}

