package main

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"maps"
	"slices"
)

// hash1 — go.sum dagi h1: xeshini hisoblash qoidasi.
func hash1(files map[string]string) string {
	h := sha256.New()
	for _, name := range slices.Sorted(maps.Keys(files)) {
		sum := sha256.Sum256([]byte(files[name]))
		fmt.Fprintf(h, "%x  %s\n", sum, name)
	}
	return "h1:" + base64.StdEncoding.EncodeToString(h.Sum(nil))
}

func main() {
	files := map[string]string{
		"example.com/hello@v1.0.0/go.mod":   "module example.com/hello\n",
		"example.com/hello@v1.0.0/hello.go": "package hello\n",
	}
	fmt.Println(hash1(files))

	files["example.com/hello@v1.0.0/hello.go"] = "package hello // o'zgargan\n"
	fmt.Println(hash1(files))
}

