import (
	"archive/zip"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"os"
	"sort"
)

func main() {
	zr, err := zip.OpenReader(os.Args[1]) // modul keshidagi .zip fayl
	if err != nil {
		panic(err)
	}
	defer zr.Close()

	files := map[string]*zip.File{}
	var names []string
	for _, f := range zr.File {
		files[f.Name] = f
		names = append(names, f.Name)
	}
	sort.Strings(names)

	h := sha256.New()
	for _, name := range names {
		r, _ := files[name].Open()
		fh := sha256.New()
		io.Copy(fh, r)
		r.Close()
		fmt.Fprintf(h, "%x  %s\n", fh.Sum(nil), name)
	}
	fmt.Println("h1:" + base64.StdEncoding.EncodeToString(h.Sum(nil)))
}

