package main

import (
	"fmt"
	"slices"
	"strings"
)

func latest(versions []string, excluded, retracted map[string]bool) string {
	var releases, pre []string
	for _, v := range versions {
		if excluded[v] || retracted[v] {
			continue
		}
		if strings.Contains(v, "-") {
			pre = append(pre, v)
		} else {
			releases = append(releases, v)
		}
	}
	if len(releases) > 0 {
		return releases[len(releases)-1] // ro'yxat o'sish tartibida
	}
	if len(pre) > 0 {
		return pre[len(pre)-1]
	}
	return "(yo'q)"
}

func main() {
	versions := []string{"v1.0.0", "v1.1.0", "v1.2.0", "v1.2.1", "v1.3.0-beta.1"}
	fmt.Println("cheklovsiz:                 ", latest(versions, nil, nil))
	fmt.Println("v1.2.1 retract qilingan:    ", latest(versions, nil, map[string]bool{"v1.2.1": true}))
	fmt.Println("v1.2.1 exclude, v1.2.0 retract:", latest(versions, map[string]bool{"v1.2.1": true}, map[string]bool{"v1.2.0": true}))
	fmt.Println("faqat pre-release bor:      ", latest(slices.Clone(versions[4:]), nil, nil))
}

