import (
	"fmt"
	"path"
	"strings"
)

func private(patterns, module string) bool {
	parts := strings.Split(module, "/")
	for _, pat := range strings.Split(patterns, ",") {
		n := strings.Count(pat, "/") + 1
		if len(parts) < n {
			continue
		}
		if ok, _ := path.Match(pat, strings.Join(parts[:n], "/")); ok {
			return true
		}
	}
	return false
}

