	"strings"
	"unicode"
)

func escape(s string) string {
	var b strings.Builder
	for _, r := range s {
		if unicode.IsUpper(r) {
			b.WriteByte('!')
			r = unicode.ToLower(r)
		}
		b.WriteRune(r)
	}
	return b.String()
}

func main() {
	const proxy = "https://proxy.golang.org"
	module, version := "github.com/google/uuid", "v1.6.0"
	base := proxy + "/" + escape(module)

	fmt.Println("versiyalar:  ", base+"/@v/list")
	fmt.Println("eng yangisi: ", base+"/@latest")
	fmt.Println("ma'lumot:    ", base+"/@v/"+version+".info")
	fmt.Println("go.mod:      ", base+"/@v/"+version+".mod")
	fmt.Println("arxiv:       ", base+"/@v/"+version+".zip")
	fmt.Println("xesh bazasi: ", "https://sum.golang.org/lookup/"+module+"@"+version)
}

