package main

import (
	"errors"
	"fmt"
	"strings"
)

func checkPath(p string) error {
	if p == "" {
		return errors.New("bo'sh yo'l")
	}
	elems := strings.Split(p, "/")
	for _, e := range elems {
		if e == "" {
			return errors.New("bo'sh element (/ bilan boshlanish, tugash yoki //)")
		}
		for _, r := range e {
			ok := r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("-._~", r)
			if !ok {
				return fmt.Errorf("%q belgisi mumkin emas", r)
			}
		}
	}
	if !strings.Contains(elems[0], ".") {
		return errors.New("yuklab bo'ladigan modul yo'lining birinchi elementida nuqta bo'lishi kerak")
	}
	return nil
}

func main() {
	for _, p := range []string{
		"github.com/aziz/hello",
		"example.com/hello",
		"hello",
		"github.com//hello",
		"example.com/my app",
		"/example.com/x",
	} {
		if err := checkPath(p); err != nil {
			fmt.Printf("%-24q XATO: %v\n", p, err)
		} else {
			fmt.Printf("%-24q OK\n", p)
		}
	}
}

