// Package isbn — ISBN-13 raqamini tekshiradi.
package isbn

// Valid ISBN-13 kontrol raqamini tekshiradi.
func Valid(s string) bool {
	sum, n := 0, 0
	for _, r := range s {
		if r < '0' || r > '9' {
			continue // defis va bo'shliqlar o'tkazib yuboriladi
		}
		d := int(r - '0')
		if n%2 == 1 {
			d *= 3
		}
		sum += d
		n++
	}
	return n == 13 && sum%10 == 0
}

