// allowed: importer imported paketni import qila oladimi?
func allowed(importer, imported string) bool {
	parts := strings.Split(imported, "/")
	for i := len(parts) - 1; i > 0; i-- {
		if parts[i] == "internal" {
			root := strings.Join(parts[:i], "/") // internal ning ota papkasi
			return importer == root || strings.HasPrefix(importer, root+"/")
		}
	}
	return true // internal yo'q: hamma import qila oladi
}

