func printTree(fsys fs.FS, dir, prefix string) {
	entries, _ := fs.ReadDir(fsys, dir)
	for i, e := range entries {
		branch, next := "├── ", "│   "
		if i == len(entries)-1 {
			branch, next = "└── ", "    "
		}
		name := e.Name()
		if e.IsDir() {
			name += "/"
		}
		fmt.Println(prefix + branch + name)
		if e.IsDir() {
			sub := e.Name()
			if dir != "." {
				sub = dir + "/" + sub
			}
			printTree(fsys, sub, prefix+next)
		}
	}
}

