		dir, pkg := path.Dir(p), f.Name.Name
		switch {
		case strings.HasPrefix(dir, "cmd/") && pkg != "main":
			fmt.Printf("XATO %-24s cmd ichida package main bo'lishi kerak (bu: %s)\n", p, pkg)
		case path.Base(dir) == "utils" || path.Base(dir) == "common":
			fmt.Printf("XATO %-24s umumiy nom: vazifani nomlang\n", p)
		case !strings.HasPrefix(dir, "cmd/") && path.Base(dir) != pkg:
			fmt.Printf("XATO %-24s paket nomi (%s) papka nomiga (%s) mos emas\n", p, pkg, path.Base(dir))
