package main

import (
	"fmt"
	"go/parser"
	"go/token"
	"slices"
	"strconv"
	"strings"
)

var sources = map[string]string{
	"shop/cmd":   "package main\nimport \"shop/user\"\n",
	"shop/user":  "package user\nimport \"shop/order\"\n",
	"shop/order": "package order\nimport \"shop/user\"\n",
}

func importsOf(src string) []string {
	f, _ := parser.ParseFile(token.NewFileSet(), "x.go", src, parser.ImportsOnly)
	var out []string
	for _, imp := range f.Imports {
		p, _ := strconv.Unquote(imp.Path.Value)
		out = append(out, p)
	}
	return out
}

func main() {
	graph := map[string][]string{}
	for pkg, src := range sources {
		graph[pkg] = importsOf(src)
	}

	state := map[string]int{} // 0 yangi, 1 yo'lda, 2 tugagan
	var stack []string
	var cycle []string
	var visit func(p string) bool
	visit = func(p string) bool {
		state[p] = 1
		stack = append(stack, p)
		for _, next := range graph[p] {
			if _, ok := graph[next]; !ok {
				continue
			}
			if state[next] == 1 {
				cycle = append(slices.Clone(stack[slices.Index(stack, next):]), next)
				return true
			}
			if state[next] == 0 && visit(next) {
				return true
			}
		}
		stack = stack[:len(stack)-1]
		state[p] = 2
		return false
	}

	if visit("shop/cmd") {
		fmt.Println("package shop/cmd")
		for _, p := range stack[1:] {
			fmt.Println("\timports", p)
		}
		fmt.Println("\timports", cycle[len(cycle)-1]+": import cycle not allowed")
		fmt.Println("aylana:", strings.Join(cycle, " -> "))
	}
}

