package main

import (
	"fmt"
	"maps"
	"slices"
)

func main() {
	// paket -> u import qiladigan paketlar (cycle yo'q)
	graph := map[string][]string{
		"shop/cmd":   {"shop/user", "shop/order"},
		"shop/user":  {"shop/order"},
		"shop/order": {},
	}

	visited := map[string]bool{}
	var order []string
	var visit func(p string)
	visit = func(p string) {
		if visited[p] {
			return
		}
		visited[p] = true
		for _, dep := range graph[p] {
			visit(dep)
		}
		order = append(order, p) // bog'liqliklar tugagach qo'shiladi
	}
	for _, p := range slices.Sorted(maps.Keys(graph)) {
		visit(p)
	}
	fmt.Println("yig'ish tartibi:", order)
}

