import (
	"fmt"
	"regexp"
)

var semver = regexp.MustCompile(`^v(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$`)

func main() {
	versions := []string{"v1.2.3", "v1.2.3-beta.1", "v2.0.0+incompatible", "1.2.3", "v1.2", "v01.2.3", "v1.2.3-rc.1+build.5"}
	for _, v := range versions {
		m := semver.FindStringSubmatch(v)
		if m == nil {
			fmt.Printf("%-21s noto'g'ri versiya\n", v)
			continue
		}
		fmt.Printf("%-21s major=%s minor=%s patch=%s pre=%q build=%q\n", v, m[1], m[2], m[3], m[4], m[5])
	}
}

package main

import "fmt"

func bump(v [3]int, change string) [3]int {
	switch change {
	case "fix":
		v[2]++
	case "feature":
		v[1], v[2] = v[1]+1, 0
	case "breaking":
		if v[0] == 0 { // v0 da buzuvchi o'zgarish minor ni oshiradi
			v[1], v[2] = v[1]+1, 0
		} else {
			v[0], v[1], v[2] = v[0]+1, 0, 0
		}
	}
	return v
}

func main() {
	cur := [3]int{1, 2, 3}
	for _, change := range []string{"fix", "feature", "breaking"} {
		n := bump(cur, change)
		fmt.Printf("v%d.%d.%d + %-8s -> v%d.%d.%d\n", cur[0], cur[1], cur[2], change, n[0], n[1], n[2])
	}
	old := [3]int{0, 9, 1}
	n := bump(old, "breaking")
	fmt.Printf("v%d.%d.%d + %-8s -> v%d.%d.%d (v0 barqaror emas)\n", old[0], old[1], old[2], "breaking", n[0], n[1], n[2])
}

package main

import (
	"cmp"
	"fmt"
	"slices"
	"strconv"
	"strings"
)

type Ver struct {
	Core [3]int
	Pre  []string
}

func parse(s string) Ver {
	s = strings.TrimPrefix(s, "v")
	core, pre, _ := strings.Cut(s, "-")
	var v Ver
	fmt.Sscanf(core, "%d.%d.%d", &v.Core[0], &v.Core[1], &v.Core[2])
	if pre != "" {
		v.Pre = strings.Split(pre, ".")
	}
	return v
}

func comparePre(a, b []string) int {
	switch {
	case len(a) == 0 && len(b) == 0:
		return 0
	case len(a) == 0:
		return 1 // reliz pre-release'dan yuqori
	case len(b) == 0:
		return -1
	}
	for i := 0; i < min(len(a), len(b)); i++ {
		x, xerr := strconv.Atoi(a[i])
		y, yerr := strconv.Atoi(b[i])
		var c int
		switch {
		case xerr == nil && yerr == nil:
			c = cmp.Compare(x, y)
		case xerr == nil:
			c = -1 // raqamli < harfli
		case yerr == nil:
			c = 1
		default:
			c = strings.Compare(a[i], b[i])
		}
		if c != 0 {
			return c
		}
	}
	return cmp.Compare(len(a), len(b))
}

func compare(a, b string) int {
	x, y := parse(a), parse(b)
	return cmp.Or(slices.Compare(x.Core[:], y.Core[:]), comparePre(x.Pre, y.Pre))
}

func main() {
	versions := []string{"v1.0.0", "v1.0.0-rc.1", "v1.0.0-beta.11", "v1.0.0-beta.2", "v1.0.0-beta",
		"v1.0.0-alpha.beta", "v1.0.0-alpha.1", "v1.0.0-alpha", "v0.9.0", "v1.0.1"}
	slices.SortFunc(versions, compare)
	for _, v := range versions {
		fmt.Println(v)
	}
}

