import (
	"fmt"
	"regexp"
	"strings"
)

var suffix = regexp.MustCompile(`^(.*)/(v[2-9]|v[1-9]\d+)$`)

func check(path, version string) error {
	major, _, _ := strings.Cut(version, ".")
	m := suffix.FindStringSubmatch(path)
	switch {
	case major == "v0" || major == "v1" || strings.HasSuffix(version, "+incompatible"):
		if m != nil {
			return fmt.Errorf("%s uchun yo'lda %s bo'lmasligi kerak", version, m[2])
		}
	case m == nil || m[2] != major:
		base := path
		if m != nil {
			base = m[1]
		}
		return fmt.Errorf("invalid version: module contains a go.mod file, so module path must match major version (%q)", base+"/"+major)
	}
	return nil
}

func main() {
