package main

import (
	"fmt"
	"slices"
	"strings"
)

var versions = []string{"v1.0.0", "v1.0.1", "v1.0.2", "v1.1.0", "v1.1.1"}

func key(v string) []int {
	var k [3]int
	fmt.Sscanf(v, "v%d.%d.%d", &k[0], &k[1], &k[2])
	return k[:]
}

func best(candidates []string) string {
	if len(candidates) == 0 {
		return "(topilmadi)"
	}
	return slices.MaxFunc(candidates, func(a, b string) int { return slices.Compare(key(a), key(b)) })
}

func resolve(query, current string) string {
	switch query {
	case "latest", "upgrade":
		return best(versions)
	case "patch":
		minor := current[:strings.LastIndex(current, ".")]
		return best(slices.DeleteFunc(slices.Clone(versions), func(v string) bool {
			return !strings.HasPrefix(v, minor+".")
		}))
	}
	// v1 yoki v1.0 kabi prefiks
	return best(slices.DeleteFunc(slices.Clone(versions), func(v string) bool {
		return !strings.HasPrefix(v, query+".")
	}))
}

func main() {
	const current = "v1.0.0"
	for _, q := range []string{"latest", "upgrade", "patch", "v1", "v1.0", "v1.1", "v2"} {
		fmt.Printf("@%-8s -> %s\n", q, resolve(q, current))
	}
}

