func nextPatch(v string) string {
	var a, b, c int
	fmt.Sscanf(v, "v%d.%d.%d", &a, &b, &c)
	return fmt.Sprintf("v%d.%d.%d", a, b, c+1)
}

func pseudo(base string, t time.Time, commit string) string {
	stamp, hash := t.UTC().Format("20060102150405"), commit[:12]
	switch {
	case base == "":
		return fmt.Sprintf("v0.0.0-%s-%s", stamp, hash)
	case strings.Contains(base, "-"): // pre-release asosida
		return fmt.Sprintf("%s.0.%s-%s", base, stamp, hash)
	default: // reliz asosida: keyingi patch + "-0."
		return fmt.Sprintf("%s-0.%s-%s", nextPatch(base), stamp, hash)
	}
}

func main() {
