package main

import (
	"fmt"
	"slices"
	"strings"
)

type Retract struct{ Low, High string }

func key(v string) []int {
	var k [3]int
	fmt.Sscanf(v, "v%d.%d.%d", &k[0], &k[1], &k[2])
	return k[:]
}

// parse "v1.2.0" yoki "[v1.0.0, v1.0.5]" ni o'qiydi.
func parse(s string) Retract {
	if strings.HasPrefix(s, "[") {
		lo, hi, _ := strings.Cut(strings.Trim(s, "[]"), ",")
		return Retract{strings.TrimSpace(lo), strings.TrimSpace(hi)}
	}
	return Retract{s, s}
}

func (r Retract) Has(v string) bool {
	return slices.Compare(key(v), key(r.Low)) >= 0 && slices.Compare(key(v), key(r.High)) <= 0
}

func main() {
	retracts := []Retract{parse("v1.2.0"), parse("[v1.0.0, v1.0.5]")}
	for _, v := range []string{"v0.9.0", "v1.0.3", "v1.0.6", "v1.2.0", "v1.2.1"} {
		status := "ishlatish mumkin"
		for _, r := range retracts {
			if r.Has(v) {
				status = "RETRACT qilingan"
			}
		}
		fmt.Printf("%-7s %s\n", v, status)
	}
}

