package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
)

func api(src string) map[string]string {
	f, _ := parser.ParseFile(token.NewFileSet(), "x.go", src, 0)
	out := map[string]string{}
	for _, d := range f.Decls {
		if fn, ok := d.(*ast.FuncDecl); ok && fn.Recv == nil && fn.Name.IsExported() {
			out[fn.Name.Name] = types.ExprString(fn.Type)
		}
	}
	return out
}

func suggest(oldSrc, newSrc string) string {
	oldAPI, newAPI := api(oldSrc), api(newSrc)
	for name, sig := range oldAPI {
		if newAPI[name] != sig {
			return fmt.Sprintf("MAJOR (%s o'zgargan yoki o'chirilgan)", name)
		}
	}
	if len(newAPI) > len(oldAPI) {
		return "MINOR (yangi funksiya qo'shilgan)"
	}
	return "PATCH (API o'zgarmagan)"
}

