package main

import (
	"fmt"
	"strings"
)

// status: har bir proksining javob kodi (soxta).
var status = map[string]int{"a": 404, "b": 500, "c": 200}

func resolve(goproxy string) string {
	entries := strings.FieldsFunc(goproxy, func(r rune) bool { return r == ',' || r == '|' })
	seps := []byte{}
	for _, r := range goproxy {
		if r == ',' || r == '|' {
			seps = append(seps, byte(r))
		}
	}
	for i, e := range entries {
		if e == "off" {
			return "off: modul topilmadi (tarmoqqa chiqilmaydi)"
		}
		code := status[e]
		if code == 200 {
			return "olindi: " + e
		}
		if i == len(seps) {
			return fmt.Sprintf("xato: %s javobi %d", e, code)
		}
		if seps[i] == ',' && code != 404 && code != 410 {
			return fmt.Sprintf("to'xtadi: %s javobi %d (vergul faqat 404/410 da o'tadi)", e, code)
		}
	}
	return "topilmadi"
}

func main() {
	for _, cfg := range []string{"a,c", "b,c", "b|c", "a,b", "a,off"} {
		fmt.Printf("GOPROXY=%-6s %s\n", cfg, resolve(cfg))
	}
}

