package main

import (
	"fmt"
	"slices"
	"strings"
)

func render(goVersion string, dirs []string) string {
	dirs = slices.Sorted(slices.Values(dirs))
	var b strings.Builder
	fmt.Fprintf(&b, "go %s\n\n", goVersion)
	if len(dirs) == 1 {
		fmt.Fprintf(&b, "use %s\n", dirs[0])
		return b.String()
	}
	b.WriteString("use (\n")
	for _, d := range dirs {
		fmt.Fprintf(&b, "\t%s\n", d)
	}
	b.WriteString(")\n")
	return b.String()
}

func main() {
	fmt.Print(render("1.27.2", []string{"./app"}))
	fmt.Println("---")
	fmt.Print(render("1.27.2", []string{"./pricing", "./api", "./tools"}))
}

package main

import (
	"fmt"
	"os"
	"path/filepath"
)

func findUp(dir, name string) string {
	for {
		if _, err := os.Stat(filepath.Join(dir, name)); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

func main() {
	root, _ := os.MkdirTemp("", "monorepo")
	defer os.RemoveAll(root)
	deep := filepath.Join(root, "api", "internal", "handler")
	os.MkdirAll(deep, 0o755)
	os.WriteFile(filepath.Join(root, "go.work"), []byte("go 1.27.2\n"), 0o644)
	os.WriteFile(filepath.Join(root, "api", "go.mod"), []byte("module example.com/shop/api\n"), 0o644)

	rel := func(p string) string {
		if p == "" {
			return "(topilmadi)"
		}
		r, _ := filepath.Rel(root, p)
		return r
	}
	fmt.Println("modul ildizi:  ", rel(findUp(deep, "go.mod")))
	for _, gowork := range []string{"", "off"} {
		work := findUp(deep, "go.work")
		if gowork == "off" {
			work = ""
		}
		fmt.Printf("GOWORK=%-4q -> workspace ildizi: %s\n", gowork, rel(work))
	}
}

package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	root, _ := os.MkdirTemp("", "mono")
	defer os.RemoveAll(root)
	for _, f := range []string{
		"api/go.mod", "api/main.go",
		"pricing/go.mod", "pricing/tools/go.mod",
		"vendor/x/go.mod", ".git/hooks/go.mod", "docs/readme.md",
	} {
		p := filepath.Join(root, f)
		os.MkdirAll(filepath.Dir(p), 0o755)
		os.WriteFile(p, []byte("x"), 0o644)
	}

	var dirs []string
	filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if d.IsDir() && (d.Name() == "vendor" || strings.HasPrefix(d.Name(), ".")) && p != root {
			return filepath.SkipDir
		}
		if !d.IsDir() && d.Name() == "go.mod" {
			rel, _ := filepath.Rel(root, filepath.Dir(p))
			dirs = append(dirs, "./"+filepath.ToSlash(rel))
		}
		return nil
	})
	fmt.Println("use:", dirs)
}

