var modules = []string{"example.com/shop", "example.com/shop/pricing", "example.com/shop/pricing/tools"}

func owner(pkg string) string {
	best := ""
	for _, m := range modules {
		if (pkg == m || strings.HasPrefix(pkg, m+"/")) && len(m) > len(best) {
			best = m
		}
	}
	if best == "" {
		return "(workspace'da yo'q)"
	}
	return best
}

