package main

import (
	"fmt"
	"maps"
	"slices"
)

type Req struct{ Module, Version string }

func key(v string) []int {
	var k [3]int
	fmt.Sscanf(v, "v%d.%d.%d", &k[0], &k[1], &k[2])
	return k[:]
}

func main() {
	requires := map[string][]Req{
		"app": {{"rsc.io/quote", "v1.5.1"}},
		"lib": {{"rsc.io/quote", "v1.5.2"}, {"example.com/util", "v1.2.0"}},
		"cli": {{"example.com/util", "v1.4.0"}},
	}

	selected := map[string]string{}
	for _, reqs := range requires {
		for _, r := range reqs {
			if cur, ok := selected[r.Module]; !ok || slices.Compare(key(r.Version), key(cur)) > 0 {
				selected[r.Module] = r.Version
			}
		}
	}

	for _, mod := range slices.Sorted(maps.Keys(requires)) {
		for _, r := range requires[mod] {
			if want := selected[r.Module]; want != r.Version {
				fmt.Printf("sync: %s go.mod: %s %s -> %s\n", mod, r.Module, r.Version, want)
			}
		}
	}
}

