package main

import (
	"fmt"
	"maps"
	"slices"
)

func main() {
	// modul -> u tayanadigan mahalliy modullar
	deps := map[string][]string{
		"api":     {"pricing", "auth"},
		"pricing": {"core"},
		"auth":    {"core"},
		"core":    {},
	}

	indegree := map[string]int{}
	for m, ds := range deps {
		indegree[m] += 0
		for range ds {
			indegree[m]++
		}
	}

	var order []string
	for len(order) < len(deps) {
		var ready []string
		for _, m := range slices.Sorted(maps.Keys(indegree)) {
			if indegree[m] == 0 {
				ready = append(ready, m)
			}
		}
		if len(ready) == 0 {
			fmt.Println("modullar orasida sikl bor")
			return
		}
		for _, m := range ready {
			order = append(order, m)
			delete(indegree, m)
			for other, ds := range deps {
				if slices.Contains(ds, m) {
					indegree[other]--
				}
			}
		}
	}
	fmt.Println("yig'ish tartibi:", order)
}

package main

import (
	"fmt"
	"slices"
	"strings"
)

var deps = map[string][]string{
	"api":     {"pricing", "auth"},
	"pricing": {"core"},
	"auth":    {"core"},
	"core":    {},
}

func affected(changed []string) []string {
	set := map[string]bool{}
	for _, f := range changed {
		mod, _, _ := strings.Cut(f, "/")
		if _, ok := deps[mod]; ok {
			set[mod] = true
		}
	}
	for grew := true; grew; { // o'zgargan modulga tayangan modullarni qo'shamiz
		grew = false
		for m, ds := range deps {
			if set[m] {
				continue
			}
			for _, d := range ds {
				if set[d] {
					set[m], grew = true, true
				}
			}
		}
	}
	var out []string
	for m := range set {
		out = append(out, m)
	}
	slices.Sort(out)
	return out
}

func main() {
	fmt.Println("core/money.go:", affected([]string{"core/money.go"}))
	fmt.Println("api/main.go:  ", affected([]string{"api/main.go", "README.md"}))
	fmt.Println("auth/token.go:", affected([]string{"auth/token.go"}))
}

