package main

import (
	"fmt"
	"strings"
)

const modulesTxt = `# golang.org/x/text v0.0.0-20170915032832-14c0d48ead0c
## explicit
golang.org/x/text/internal/tag
golang.org/x/text/language
# rsc.io/quote v1.5.2
## explicit
rsc.io/quote
# rsc.io/sampler v1.3.0
## explicit
rsc.io/sampler
`

func main() {
	owner := map[string]string{}
	current := ""
	for _, line := range strings.Split(modulesTxt, "\n") {
		switch {
		case line == "" || strings.HasPrefix(line, "##"):
		case strings.HasPrefix(line, "# "):
			current = strings.TrimPrefix(line, "# ")
		default:
			owner[line] = current
		}
	}

	for _, pkg := range []string{"golang.org/x/text/language", "rsc.io/sampler", "fmt", "rsc.io/quote/buggy"} {
		if m, ok := owner[pkg]; ok {
			fmt.Printf("%-28s <- %s\n", pkg, m)
		} else {
			fmt.Printf("%-28s vendor/ da yo'q\n", pkg)
		}
	}
}

