package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing/fstest"
)

func main() {
	cache := fstest.MapFS{
		"rsc.io/quote/quote.go":                  {Data: []byte("package quote")},
		"rsc.io/quote/quote_test.go":             {Data: []byte("package quote")},
		"rsc.io/quote/LICENSE":                   {Data: []byte("BSD")},
		"rsc.io/quote/buggy/buggy_test.go":       {Data: []byte("package buggy")},
		"golang.org/x/text/language/language.go": {Data: []byte("package language")},
		"golang.org/x/text/language/tables.go":   {Data: []byte("package language")},
		"golang.org/x/text/cldr/cldr.go":         {Data: []byte("package cldr")},
		"golang.org/x/text/internal/tag/tag.go":  {Data: []byte("package tag")},
	}
	used := []string{"rsc.io/quote", "golang.org/x/text/language", "golang.org/x/text/internal/tag"}

	vendor, _ := os.MkdirTemp("", "vendor")
	defer os.RemoveAll(vendor)
	skipped := 0
	fs.WalkDir(cache, ".", func(p string, d fs.DirEntry, err error) error {
		if d.IsDir() {
			return nil
		}
		dir := filepath.ToSlash(filepath.Dir(p))
		isLicense := d.Name() == "LICENSE"
		if !(isLicense || (slices.Contains(used, dir) && !strings.HasSuffix(p, "_test.go"))) {
			skipped++
			return nil
		}
		data, _ := fs.ReadFile(cache, p)
		os.MkdirAll(filepath.Join(vendor, filepath.Dir(p)), 0o755)
		return os.WriteFile(filepath.Join(vendor, p), data, 0o644)
	})

	fmt.Println("vendor/ tarkibi:")
	fs.WalkDir(os.DirFS(vendor), ".", func(p string, d fs.DirEntry, err error) error {
		if !d.IsDir() {
			fmt.Println(" ", p)
		}
		return nil
	})
	fmt.Println("o'tkazib yuborilgan fayllar:", skipped)
}

package main

import (
	"fmt"
	"maps"
	"slices"
)

func main() {
	goMod := map[string]string{"rsc.io/quote": "v1.5.1", "rsc.io/sampler": "v1.3.0"}
	explicit := map[string]string{"rsc.io/quote": "v1.5.2", "rsc.io/sampler": "v1.3.0"} // modules.txt

	var problems []string
	for _, m := range slices.Sorted(maps.Keys(goMod)) {
		if explicit[m] != goMod[m] {
			problems = append(problems, fmt.Sprintf("%s@%s: is explicitly required in go.mod, but not marked as explicit in vendor/modules.txt", m, goMod[m]))
		}
	}
	for _, m := range slices.Sorted(maps.Keys(explicit)) {
		if goMod[m] != explicit[m] {
			problems = append(problems, fmt.Sprintf("%s@%s: is marked as explicit in vendor/modules.txt, but not explicitly required in go.mod", m, explicit[m]))
		}
	}

	if len(problems) == 0 {
		fmt.Println("vendor/ go.mod ga mos")
		return
	}
	fmt.Println("inconsistent vendoring:")
	for _, p := range problems {
		fmt.Println("\t" + p)
	}
	fmt.Println("tuzatish: go mod vendor")
}

package main

import (
	"fmt"
	"go/version"
)

func defaultMod(goVersion string, hasVendor bool, flag string) string {
	switch {
	case flag != "":
		return flag + " (bayroq bilan belgilangan)"
	case hasVendor && version.Compare("go"+goVersion, "go1.14") >= 0:
		return "vendor"
	default:
		return "readonly"
	}
}

func main() {
	fmt.Println("go 1.27.2, vendor/ yo'q:        ", defaultMod("1.27.2", false, ""))
	fmt.Println("go 1.27.2, vendor/ bor:         ", defaultMod("1.27.2", true, ""))
	fmt.Println("go 1.13,   vendor/ bor:         ", defaultMod("1.13", true, ""))
	fmt.Println("go 1.27.2, vendor/ bor, -mod=mod:", defaultMod("1.27.2", true, "mod"))
}

