func main() {
	vendor := fstest.MapFS{
		"vendor/rsc.io/quote/LICENSE":                  {Data: []byte("Copyright 2018 The Go Authors.\nBSD-3-Clause")},
		"vendor/rsc.io/quote/quote.go":                 {Data: []byte("package quote")},
		"vendor/rsc.io/sampler/LICENSE":                {Data: []byte("Copyright 2018 The Go Authors.\nBSD-3-Clause")},
