	}

	withLicense := map[string]string{}
	fs.WalkDir(vendor, "vendor", func(p string, d fs.DirEntry, err error) error {
		if !d.IsDir() && d.Name() == "LICENSE" {
			data, _ := fs.ReadFile(vendor, p)
			first, _, _ := strings.Cut(string(data), "\n")
